import java.util.Scanner;

public class Main {
    static final int MAXN = 1000009;
    static final long MODULUS = 1000000007L;

    static long computePower(long base, long exp, long mod) {
        long res = 1;
        long b = base;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                res = (res * b) % mod;
            }
            b = (b * b) % mod;
            exp >>= 1;
        }
        return res;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int p = sc.nextInt();
        int k = sc.nextInt();
        int[] visitedArray = new int[p];
        int result = 1;

        if (k == 0) {
            for (int i = 1; i < p; ++i) {
                result = (int)((long)result * p % MODULUS);
            }
            System.out.println(result);
            sc.close();
            return;
        }

        for (int i = 0; i < p; ++i) {
            if (visitedArray[i] != 0) continue;
            int j = i, d = 0;
            do {
                visitedArray[j] = ++d;
                j = (int)(((long)j * k) % p);
            } while (visitedArray[j] == 0);
            if (computePower(k, d, p) == 1)
                result = (int)((long)result * p % MODULUS);
        }
        System.out.println(result);
        sc.close();
    }
}
